+void mc_debug_poll_drain(void)
+{
+    uint16_t budget = MC_DBG_DRAIN_BUDGET;
+    while ((budget > 0U) && (s_mc_dbg_tail != s_mc_dbg_head))
+    {
+        if (usart_flag_get(USART1, USART_TDBE_FLAG) == RESET)
+        {
+            break;
+        }
+        const uint8_t byte_val = s_mc_dbg_ring[s_mc_dbg_tail];
+        s_mc_dbg_tail = (uint16_t)((s_mc_dbg_tail + 1U) % MC_DBG_RING_CAPACITY);
+        usart_data_transmit(USART1, (uint16_t)byte_val);
+        budget--;
+    }
+}
