+static void test_th_relay_correlation_and_nack(void)
+{
+    printf("[RUN ] test_th_relay_correlation_and_nack\n");
+    minimc_proto_init();
+    clear_usart1_capture();
+    s_mock_tick_ms = 5000U;
+    s_test_seq = 50U;
+    const uint32_t tx_base = s_ap_tx_count;
+    /* 1. Unsolicited TH frame with no pending relay -> rejected as BAD_FRAME (0x07), not forwarded */
+    inject_th_response_frame(MINIMC_CMD_VERSION_REPORT, 50U);
+    assert(s_ap_tx_count == tx_base);
+    assert(strstr(s_usart1_tx_capture, "dir=ERR node=TH seq=50 cmd=0x02 status=BAD_FRAME err_code=0x07") != NULL);
+    assert(strstr(s_usart1_tx_capture, "dir=RELAY_RX") == NULL);
+    /* 2. Pending relay (seq=51, cmd=0x01): mismatched seq (99) & mismatched cmd (0x04) do NOT clear pending */
+    clear_usart1_capture();
+    send_test_frame(MINIMC_NODE_TH, MINIMC_CMD_GET_VERSION, NULL, 0U);
+    inject_th_response_frame(MINIMC_CMD_VERSION_REPORT, 99U);
+    inject_th_response_frame(MINIMC_CMD_PONG, 51U);
+    assert(s_ap_tx_count == tx_base);
+    assert(strstr(s_usart1_tx_capture, "dir=ERR node=TH seq=99 cmd=0x02 status=BAD_FRAME err_code=0x07") != NULL);
+    assert(strstr(s_usart1_tx_capture, "dir=ERR node=TH seq=51 cmd=0x04 status=BAD_FRAME err_code=0x07") != NULL);
+    assert(strstr(s_usart1_tx_capture, "dir=RELAY_RX node=TH") == NULL);
+    /* Valid matching TH response (seq=51, cmd=0x02) arrives at +20ms -> succeeds and clears pending */
+    s_mock_tick_ms = 5020U;
+    inject_th_response_frame(MINIMC_CMD_VERSION_REPORT, 51U);
+    assert(s_ap_tx_count == tx_base + 1U);
+    assert(strstr(s_usart1_tx_capture, "dir=RELAY_RX node=TH seq=51 cmd=0x02 status=ACK elapsed_ms=20") != NULL);
+    assert(strstr(s_usart1_tx_capture, "dir=TX node=TH seq=51 cmd=0x02 status=ACK elapsed_ms=20") != NULL);
+    /* 3. Pending relay (seq=52, cmd=0x01): mismatched seq (88) must NOT disarm timeout */
+    clear_usart1_capture();
+    send_test_frame(MINIMC_NODE_TH, MINIMC_CMD_GET_VERSION, NULL, 0U);
+    inject_th_response_frame(MINIMC_CMD_VERSION_REPORT, 88U);
+    s_mock_tick_ms = 5270U;
+    minimc_proto_poll();
+    drain_all_usart1();
+    assert(strstr(s_usart1_tx_capture, "dir=RELAY_RX node=TH seq=52 cmd=0x01 status=TIMEOUT elapsed_ms=250") != NULL);
+    /* 4. Pending relay (seq=53, cmd=0x01): valid TH NACK (0x06, err_code=0x04) logs status=NACK */
+    clear_usart1_capture();
+    send_test_frame(MINIMC_NODE_TH, MINIMC_CMD_GET_VERSION, NULL, 0U);
+    const uint8_t nack_pay[3] = { 0x04U, 53U, 0U };
+    s_mock_tick_ms = 5285U;
+    inject_th_custom_frame(MINIMC_CMD_NACK, 53U, nack_pay, 3U);
+    assert(strstr(s_usart1_tx_capture, "dir=RELAY_RX node=TH seq=53 cmd=0x06 status=NACK err_code=0x04 elapsed_ms=15") != NULL);
+    assert(strstr(s_usart1_tx_capture, "dir=TX node=TH seq=53 cmd=0x06 status=NACK err_code=0x04 elapsed_ms=15") != NULL);
+    printf("[PASS] test_th_relay_correlation_and_nack\n");
+}
